INSERT INTO `sanpham` VALUES (1,'Sách Toán Lớp 10','Sách Giáo Khoa','Sách giáo khoa môn Toán lớp 10',50000.00,100,'toan10.jpg'),(2,'Sách Văn Lớp 10','Sách Giáo Khoa','Sách giáo khoa môn Văn lớp 10',45000.00,80,'van10.jpg'),(3,'Bút Bi Thiên Long','Văn Phòng Phẩm','Bút bi màu xanh, thương hiệu Thiên Long',5000.00,200,'butbi.jpg'),(4,'Tập Vở 200 Trang','Văn Phòng Phẩm','Tập vở 200 trang, giấy trắng mịn',15000.00,150,'tapvo.jpg'),(5,'Sách Lịch Sử Lớp 10','Sách Giáo Khoa','Sách giáo khoa môn Lịch Sử lớp 10',40000.00,50,'lichsu10.jpg'),(6,'Sách Địa Lý Lớp 10','Sách Giáo Khoa','Sách giáo khoa môn Địa Lý lớp 10',42000.00,60,'dialy10.jpg'),(7,'Bút Chì 2B','Văn Phòng Phẩm','Bút chì 2B dùng để vẽ và viết',3000.00,100,'butchi.jpg'),(8,'Tẩy Gôm','Văn Phòng Phẩm','Tẩy gôm chất lượng cao',2000.00,150,'taygom.jpg'),(9,'Thước Kẻ 30cm','Văn Phòng Phẩm','Thước kẻ dài 30cm, nhựa trong suốt',8000.00,80,'thuocke.jpg'),(10,'Bình Nước Giữ Nhiệt','Phụ Kiện','Bình nước giữ nhiệt 500ml',120000.00,25,'binhnuoc.jpg'),(11,'N/A','','N/A',0.00,100,'N/A'),(12,'string','string','string',0.00,0,'string'),(13,'Túi bút bi, bút gel Thiên Long TL-095, TL-105, FL-04/Luck - Phiên bản hanh thông thi cử, đóng gói - Túi 2/3 bút','Thiên Long','Thiên Long mong muốn mọi việc trong cuộc sống của khách hàng sẽ diễn ra một cách trôi chảy, không gặp phải trở ngại nào. Từ công việc đến học tập, mọi thứ đều được mong muốn sẽ thuận buồm xuôi gió. BST Phiên bản Đậu Xuất xứ Việt Nam Sản xuất Việt Nam Khuyến cáo Tránh nguồn nhiệt, hóa chất. Không thích hợp cho trẻ dưới 3 tuổi Bút có thiết kế hiện đại, kết hợp hài hòa giữa phần thân dưới bằng nhựa nhiều màu sắc và thon dài. Cảm giác cầm bút rất thoải mái, viết rất êm. Nét viết thanh mảnh và sắc nét. Đặc tính sản phẩm:- Cây bút đẹp, nhỏ nhọn khá nhẹ nhàng, thú vị, nét viết trơn êm, sắc sảo, chữ viết đẹp.',24000.00,100,'https://product.hstatic.net/1000230347/product/7c4308e2f00147bea13d60db005e630e_tplv-o3syd03w52-origin-jpeg_1__b75160a1711e446c85b3e318d9d478ce.jpeg'),(14,'Combo 10 Ream giấy A4 70 gsm Thiên Long Copy Plus PP-003 (500 tờ)','Copy Plus','Thông Số Kỹ Thuật: Thương hiệu Copy Plus Kích thước A4 Định lượng 70 gsm Tiêu chuẩn TCCS 066:2012/TL-PP Đóng gói 500 tờ/ ream Xuất xứ Việt Nam Sản xuất/ Nguồn giấy Nhập khẩu Khuyến cáo Nhiệt độ: 10 ~ 55º C, Độ ẩm: 55 ~ 95% RH. Copy Plus - Sự lựa chọn thích hợp cho mọi nhu cầu sử dụng. Thiết kế vượt trội chạy trên máy photocopy tốc độ cao, số lượng nhiều, đã được kiểm chứng và tin dùng bởi chất lượng vận hành đồng bộ, không kẹt giấy. Đặc điểm sản phẩm: - Giấy đều màu. - Không gợn sóng, không xơ xước và không tách lớp. - Giấy láng, không bị đốm khác màu hay tạp chất xơ cứng. - Chữ in không bị nhòe, không lem kể cả in 2 mặt giấy. Thích hợp sử dụng: - Thư tín, Báo cáo, Photocopy.',1000000.00,100,'https://product.hstatic.net/1000230347/product/artboard_2_900c8818440c44b992bc6712c9a6f96b.jpg'),(15,'Ream giấy A4 70 gsm Thiên Long Copy Plus PP-003 (500 tờ)','Copy Plus','Thông Số Kỹ Thuật: Thương hiệu Copy Plus Kích thước A4 Định lượng 70 gsm Tiêu chuẩn TCCS 066:2012/TL-PP Đóng gói 500 tờ/ ream Xuất xứ Việt Nam Sản xuất/ Nguồn giấy Nhập khẩu Khuyến cáo Nhiệt độ: 10 ~ 55º C, Độ ẩm: 55 ~ 95% RH. Copy Plus - Sự lựa chọn thích hợp cho mọi nhu cầu sử dụng. Thiết kế vượt trội chạy trên máy photocopy tốc độ cao, số lượng nhiều, đã được kiểm chứng và tin dùng bởi chất lượng vận hành đồng bộ, không kẹt giấy. Đặc điểm sản phẩm: - Giấy đều màu. - Không gợn sóng, không xơ xước và không tách lớp. - Giấy láng, không bị đốm khác màu hay tạp chất xơ cứng. - Chữ in không bị nhòe, không lem kể cả in 2 mặt giấy. Thích hợp sử dụng: - Thư tín, Báo cáo, Photocopy.',87000.00,100,'https://product.hstatic.net/1000230347/product/artboard_2_e9d0221548fb4fafb75cde9533bbcddf.jpg'),(16,'Combo 5 Ream giấy A4 70 gsm Thiên Long Copy Plus PP-003 (500 tờ)','Copy Plus','Thông Số Kỹ Thuật: Thương hiệu Copy Plus Kích thước A4 Định lượng 70 gsm Tiêu chuẩn TCCS 066:2012/TL-PP Đóng gói 500 tờ/ ream Xuất xứ Việt Nam Sản xuất/ Nguồn giấy Nhập khẩu Khuyến cáo Nhiệt độ: 10 ~ 55º C, Độ ẩm: 55 ~ 95% RH. Copy Plus - Sự lựa chọn thích hợp cho mọi nhu cầu sử dụng. Thiết kế vượt trội chạy trên máy photocopy tốc độ cao, số lượng nhiều, đã được kiểm chứng và tin dùng bởi chất lượng vận hành đồng bộ, không kẹt giấy. Đặc điểm sản phẩm: - Giấy đều màu. - Không gợn sóng, không xơ xước và không tách lớp. - Giấy láng, không bị đốm khác màu hay tạp chất xơ cứng. - Chữ in không bị nhòe, không lem kể cả in 2 mặt giấy. Thích hợp sử dụng: - Thư tín, Báo cáo, Photocopy.',500000.00,100,'https://product.hstatic.net/1000230347/product/artboard_3_copy_fffea6540f92477088e4b18c3f854778.jpg'),(17,'Bút Gel - Gel xóa được Thiên Long - Mua 5 tặng 1','Thiên Long','Thông số kĩ thuật : Tên danh mục Bút Gel Thương hiệu Thiên Long Đường kính viên bi 0.5 mm Xuất xứ Việt Nam Sản xuất Việt Nam Khuyến cáo Tránh nguồn nhiệt, hóa chất. Không thích hợp cho trẻ dưới 3 tuổi. Bút Gel là nhãn hàng Bút viết ra đời nhằm mang đến sự tiện lợi, thoải mái cho người sử dụng. Thiết kế bút phù hợp với người Việt, tạo cho người viết không bị mỏi tay. Đầu bi cao cấp giúp mực trợn mượt, phù hợp cho người viết nhiều, tốc ký như học sinh phổ thông, sinh viên. Với thiết kế trang nhã, màu sắc tươi sáng phù hợp với nhu cầu sử dụng của nhiều người, Bút Gel đã trở thành người bạn đồng hành của nhiều học sinh.',74000.00,100,'https://product.hstatic.net/1000230347/product/banner_4_dcecff80a8624c46b05d54b9bc67d45f_1__4b15247002d84f4d9d8980871acca8b7.png'),(18,'Bút gel Colochi Thiên Long Gel-050','Thiên Long','Thông số kĩ thuật : Thương hiệu Thiên Long Đường kính viên bi 0.5 mm Kích thước 141.15 mm Tiêu chuẩn TCCS 020:2011/TL-GEL Xuất xứ Việt Nam Sản xuất Việt Nam Khuyến cáo Tránh nguồn nhiệt, hóa chất. Không thích hợp cho trẻ dưới 3 tuổi.',12000.00,100,'https://product.hstatic.net/1000230347/product/gel-050_2_54df204706ab4f7899001d6c191792f3.jpg'),(19,'Cặp học sinh Strive Thiên Long - Balo teen thời trang, phù hợp đi học, đi chơi, đệm mút êm','Thiên Long','Sản phẩm Thiên Long có thiết kế mặt sau với nhiều cải tiến như: đệm mút dày dặn hơn… Kết hợp với chất liệu siêu nhẹ và bền, giúp bé thoải mái và dễ dàng di chuyển. ?TÍNH NĂNG SẢN PHẨM ▪️ Có thể điều chỉnh dây đeo phù hợp với từng bé. ▪️ Chống bụi nấm mốc, chống nước nhẹ và chống thấm. ▪️ Ngăn chứa rộng rãi giúp giữ thẳng tập sách, có túi phụ co dãn. ?THÔNG SỐ KỸ THUẬT ▪️ Xuất xứ: Việt Nam. ▪️ Kích thước: 370x260x150mm (dài x ngang x rộng). ▪️ Trọng lượng: 700 gram. ▪️ Tải trọng: tối đa 8kg. ▪️ Bảo hành: 12 tháng. ▪️ Bảo quản: Không thích hợp cho trẻ dưới 3 tuổi. Bảo quản nơi khô ráo, thoáng mát, tuyệt đối tránh xa nguồn nhiệt. Không ngâm giặt trong nước có chất tẩy, không phơi trực tiếp dưới ánh nắng mặt trời.',380000.00,100,'https://product.hstatic.net/1000230347/product/artboard_6_copy_4ad15ccae6e84d0ab9cbed07e45894c2.jpg'),(20,'Cặp chống gù Thiên Long - Jungle Dino - Glubby','Thiên Long','Sản phẩm Cặp chống gù Thiên Long có hệ thống chống gù toàn diện, thiết kế mặt sau với nhiều cải tiến như: quai đeo trợ lực, đệm mút dày dặn hơn… Kết hợp với chất liệu siêu nhẹ và bền, giúp bé thoải mái và dễ dàng di chuyển. Thiết kế 360 độ tiện lợi khi vệ sinh. ?TÍNH NĂNG SẢN PHẨM ▪️ Chống gù toàn diện với đệm mút dày êm giúp chống xô lệch, quai đeo trợ lực, đệm lưng thoát khí, nút điều chỉnh độ dài dây đeo, dây cài ngực. ▪️ Có thể điều chỉnh dây đeo phù hợp với từng bé. ▪️ Cặp mở được 360 độ vệ sinh dễ dàng. ▪️ Chống bụi nấm mốc, chống nước nhẹ và chống thấm. ▪️ Ngăn chứa rộng rãi giúp giữ thẳng tập sách, có túi phụ co dãn. ?THÔNG SỐ KỸ THUẬT ▪️ Xuất xứ: Việt Nam. ▪️ Kích thước: 370x260x150mm (dài x ngang x rộng). ▪️ Trọng lượng: 700 gram. ▪️ Tải trọng: tối đa 8kg. ▪️ Bảo hành: 12 tháng. ?HƯỚNG DẪN SỬ DỤNG VÀ BẢO QUẢN ▪️ Hướng dẫn sử dụng: Đeo balo đúng tư thế, ngay ngắn và đều hai bên, tránh đeo lệch 1 vai. Không chứa đồ quá tải trọng tối đa. ▪️ Bảo quản: Không thích hợp cho trẻ dưới 3 tuổi. Bảo quản nơi khô ráo, thoáng mát, tuyệt đối tránh xa nguồn nhiệt. Không ngâm giặt trong nước có ch